#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by spark/ring/mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enp1s0f0np0 | grep clsact >/dev/null || tc qdisc add dev enp1s0f0np0 clsact
tc qdisc show dev enp1s0f1np1 | grep clsact >/dev/null || tc qdisc add dev enp1s0f1np1 clsact
tc filter replace dev enp1s0f1np1 ingress protocol 0x88b5 pref 49156 handle 49156 flower skip_sw src_mac 4c:bb:47:80:f3:29 dst_mac 4c:bb:47:80:b2:0d action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:ab:af pipe action mirred egress redirect dev enp1s0f0np0
tc -s filter show dev enp1s0f1np1 ingress pref 49156 | grep -F -- 'eth_type 88b5' >/dev/null || { echo 'rule pref 49156 on enp1s0f1np1 does not match the generated selector/action: eth_type 88b5'; exit 3; }
tc -s filter show dev enp1s0f1np1 ingress pref 49156 | grep -F -- 'src_mac 4c:bb:47:80:f3:29' >/dev/null || { echo 'rule pref 49156 on enp1s0f1np1 does not match the generated selector/action: src_mac 4c:bb:47:80:f3:29'; exit 3; }
