tc -s filter show dev enp1s0f1np1 ingress pref 49156 | grep -F -- in_hw >/dev/null || { echo 'rule pref 49156 on enp1s0f1np1 does not match the generated selector/action: in_hw'; exit 3; }
tc -s filter show dev enp1s0f1np1 ingress pref 49156 | grep -F -- 'Redirect to device enp1s0f0np0' >/dev/null || { echo 'rule pref 49156 on enp1s0f1np1 does not match the generated selector/action: Redirect to device enp1s0f0np0'; exit 3; }
tc filter replace dev enp1s0f0np0 ingress protocol 0x88b5 pref 49166 handle 49166 flower skip_sw src_mac 4c:bb:47:80:ab:af dst_mac 4c:bb:47:80:b2:0c action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:f3:29 pipe action mirred egress redirect dev enp1s0f1np1
tc -s filter show dev enp1s0f0np0 ingress pref 49166 | grep -F -- 'eth_type 88b5' >/dev/null || { echo 'rule pref 49166 on enp1s0f0np0 does not match the generated selector/action: eth_type 88b5'; exit 3; }
tc -s filter show dev enp1s0f0np0 ingress pref 49166 | grep -F -- 'src_mac 4c:bb:47:80:ab:af' >/dev/null || { echo 'rule pref 49166 on enp1s0f0np0 does not match the generated selector/action: src_mac 4c:bb:47:80:ab:af'; exit 3; }
tc -s filter show dev enp1s0f0np0 ingress pref 49166 | grep -F -- 'dst_mac 4c:bb:47:80:b2:0c' >/dev/null || { echo 'rule pref 49166 on enp1s0f0np0 does not match the generated selector/action: dst_mac 4c:bb:47:80:b2:0c'; exit 3; }
tc -s filter show dev enp1s0f0np0 ingress pref 49166 | grep -F -- skip_sw >/dev/null || { echo 'rule pref 49166 on enp1s0f0np0 does not match the generated selector/action: skip_sw'; exit 3; }
