ip route replace 10.100.241.14/32 via 10.100.241.10 dev enP2p1s0f0np0 src 10.100.241.9
ip route replace 10.251.20.1/32 via 10.251.20.5 dev enp1s0f1np1 src 10.251.20.6
for d in roceP2p1s0f0 rocep1s0f1; do systemctl start spark-ring-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f0 rocep1s0f1; do systemctl is-active --quiet spark-ring-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
ip route show exact 10.100.241.14/32 | grep -F -- 'via 10.100.241.10' >/dev/null || { echo route 10.100.241.14/32 does not match the generated next hop: via 10.100.241.10; exit 5; }
ip route show exact 10.100.241.14/32 | grep -F -- 'dev enP2p1s0f0np0' >/dev/null || { echo route 10.100.241.14/32 does not match the generated next hop: dev enP2p1s0f0np0; exit 5; }
ip route show exact 10.100.241.14/32 | grep -F -- 'src 10.100.241.9' >/dev/null || { echo route 10.100.241.14/32 does not match the generated next hop: src 10.100.241.9; exit 5; }
ip route show exact 10.251.20.1/32 | grep -F -- 'via 10.251.20.5' >/dev/null || { echo route 10.251.20.1/32 does not match the generated next hop: via 10.251.20.5; exit 5; }
ip route show exact 10.251.20.1/32 | grep -F -- 'dev enp1s0f1np1' >/dev/null || { echo route 10.251.20.1/32 does not match the generated next hop: dev enp1s0f1np1; exit 5; }
ip route show exact 10.251.20.1/32 | grep -F -- 'src 10.251.20.6' >/dev/null || { echo route 10.251.20.1/32 does not match the generated next hop: src 10.251.20.6; exit 5; }
